/* Strict display override for hidden attribute */
[hidden] {
  display: none !important;
}

/* 4-Color Retro Palette */
:root {
  --bg-color: #1a102f;
  --card-bg: #2d1b4e;
  --pixel-accent: #f4b41b;
  --pixel-highlight: #45b6fe;
  --text-main: #f5f5f5;
  --text-dim: #b8b0cf;
  --btn-bg: #3f266d;
  --btn-hover: #583399;
  --pixel-border: #0d0718;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--bg-color);
  color: var(--text-main);
  font-family: 'Courier New', Courier, monospace, system-ui, sans-serif;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 1rem;
  background-image:
    radial-gradient(circle at 50% 50%, rgba(69, 182, 254, 0.08) 1px, transparent 1px),
    radial-gradient(circle at 20% 20%, rgba(244, 180, 27, 0.08) 1px, transparent 1px);
  background-size: 24px 24px;
}

.quiz-container {
  width: 100%;
  max-width: 540px;
  min-width: 320px;
  background-color: var(--card-bg);
  border: 4px solid var(--pixel-border);
  box-shadow:
    -6px 0 0 0 var(--pixel-border),
    6px 0 0 0 var(--pixel-border),
    0 -6px 0 0 var(--pixel-border),
    0 6px 0 0 var(--pixel-border),
    8px 8px 0 0 rgba(0, 0, 0, 0.6);
  padding: 1.75rem 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.quiz-header {
  border-bottom: 4px solid var(--pixel-border);
  padding-bottom: 1rem;
  text-align: center;
}

.pixel-title {
  font-size: 1.75rem;
  letter-spacing: 3px;
  color: var(--pixel-accent);
  text-shadow: 2px 2px 0 #000;
  margin-bottom: 0.75rem;
}

.hud-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: var(--pixel-border);
  padding: 0.5rem 1rem;
  border: 2px solid var(--pixel-accent);
}

.hud-item {
  display: flex;
  gap: 0.5rem;
  font-weight: bold;
  font-size: 1.1rem;
}

.hud-label {
  color: var(--text-dim);
}

.hud-value {
  color: var(--pixel-highlight);
  min-width: 2.5ch;
  text-align: right;
}

.screen {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.25rem;
  text-align: center;
}

.screen-desc {
  font-size: 1.1rem;
  line-height: 1.5;
  color: var(--text-dim);
  padding: 1rem 0;
}

.progress-indicator {
  font-size: 0.95rem;
  color: var(--pixel-highlight);
  letter-spacing: 1.5px;
  font-weight: bold;
  align-self: flex-start;
}

.question-heading {
  font-size: 1.25rem;
  line-height: 1.4;
  text-align: left;
  width: 100%;
  min-height: 3.5rem;
  color: var(--text-main);
}

.answers-grid {
  display: flex;
  flex-direction: column;
  width: 100%;
  gap: 0.75rem;
}

.pixel-btn {
  appearance: none;
  background-color: var(--btn-bg);
  color: var(--text-main);
  border: 3px solid var(--pixel-border);
  box-shadow:
    -3px 0 0 0 var(--pixel-border),
    3px 0 0 0 var(--pixel-border),
    0 -3px 0 0 var(--pixel-border),
    0 3px 0 0 var(--pixel-border),
    0 4px 0 0 #000;
  padding: 0.85rem 1.25rem;
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  cursor: pointer;
  text-align: center;
  text-decoration: none;
  user-select: none;
  transition: background-color 0.1s ease;
}

.pixel-btn:hover {
  background-color: var(--btn-hover);
  color: #fff;
}

.pixel-btn:focus-visible {
  outline: 3px dashed var(--pixel-accent);
  outline-offset: 4px;
}

.pixel-btn:active {
  transform: translateY(2px);
  box-shadow:
    -3px 0 0 0 var(--pixel-border),
    3px 0 0 0 var(--pixel-border),
    0 -3px 0 0 var(--pixel-border),
    0 3px 0 0 var(--pixel-border),
    0 2px 0 0 #000;
}

.answer-option {
  width: 100%;
  text-align: left;
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.option-prefix {
  color: var(--pixel-accent);
  font-weight: bold;
}

.result-heading {
  font-size: 1.6rem;
  letter-spacing: 2px;
  color: var(--pixel-accent);
}

.result-reason {
  color: var(--text-dim);
  font-size: 1.05rem;
}

.final-score-box {
  background-color: var(--pixel-border);
  border: 3px solid var(--pixel-highlight);
  padding: 1.25rem 2.5rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
}

.score-label {
  font-size: 0.95rem;
  letter-spacing: 1px;
  color: var(--text-dim);
}

.score-big {
  font-size: 2.25rem;
  color: var(--pixel-accent);
  font-weight: bold;
}

@media (max-width: 440px) {
  .quiz-container {
    padding: 1.25rem 1rem;
  }
  .pixel-title {
    font-size: 1.4rem;
  }
  .question-heading {
    font-size: 1.1rem;
  }
  .hud-bar {
    padding: 0.4rem 0.6rem;
  }
  .hud-item {
    font-size: 0.95rem;
  }
}

const QUESTIONS = [
  {
    question: "What does 'RGB' stand for in digital graphics?",
    options: ["Red, Green, Blue", "Real Graphic Bits", "Raster Grid Block", "Radial Glow Base"],
    answer: 0
  },
  {
    question: "How many bits are in a standard single byte?",
    options: ["4 bits", "8 bits", "16 bits", "32 bits"],
    answer: 1
  },
  {
    question: "Which classic console popularized 8-bit pixel art in 1983?",
    options: ["Atari 2600", "Sega Genesis", "NES / Famicom", "PlayStation"],
    answer: 2
  },
  {
    question: "What is the main purpose of CSS 'image-rendering: pixelated'?",
    options: ["Blur images", "Sharpen pixel edges on scale", "Add 3D lighting", "Compress file size"],
    answer: 1
  },
  {
    question: "What is the hex color code for pure bright white?",
    options: ["#000000", "#111111", "#EEEEEE", "#FFFFFF"],
    answer: 3
  }
];

const TOTAL_TIME = 60;
let timeRemaining = TOTAL_TIME;
let currentQuestionIndex = 0;
let score = 0;
let timerInterval = null;

// DOM Elements
const timerDisplay = document.getElementById("timer-display");
const scoreDisplay = document.getElementById("score-display");
const startScreen = document.getElementById("start-screen");
const questionScreen = document.getElementById("question-screen");
const resultScreen = document.getElementById("result-screen");
const startBtn = document.getElementById("start-btn");
const restartBtn = document.getElementById("restart-btn");
const questionNumberEl = document.getElementById("question-number");
const questionTextEl = document.getElementById("question-text");
const answersContainer = document.getElementById("answers-container");
const resultReasonEl = document.getElementById("result-reason");
const finalScoreEl = document.getElementById("final-score");

function updateHUD() {
  timerDisplay.textContent = `${timeRemaining}s`;
  scoreDisplay.textContent = `${score}`;
}

function startQuiz() {
  score = 0;
  currentQuestionIndex = 0;
  timeRemaining = TOTAL_TIME;
  updateHUD();

  startScreen.hidden = true;
  resultScreen.hidden = true;
  questionScreen.hidden = false;

  startTimer();
  renderQuestion();
}

function startTimer() {
  clearInterval(timerInterval);
  timerInterval = setInterval(() => {
    timeRemaining -= 1;
    if (timeRemaining <= 0) {
      timeRemaining = 0;
      updateHUD();
      endQuiz("Time's up!");
    } else {
      updateHUD();
    }
  }, 1000);
}
 textAlign = "left";
function renderQuestion() {
  if (currentQuestionIndex >= QUESTIONS.length) {
    endQuiz("All questions answered!");
    return;
  }

  const current = QUESTIONS[currentQuestionIndex];
  questionNumberEl.textContent = `QUESTION ${currentQuestionIndex + 1} / ${QUESTIONS.length}`;
  questionTextEl.textContent = current.question;
  answersContainer.innerHTML = "";

  const prefixes = ["A", "B", "C", "D"];
  current.options.forEach((optionText, index) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "pixel-btn answer-option";
    btn.setAttribute("aria-label", `Option ${prefixes[index]}: ${optionText}`);

    const prefixSpan = document.createElement("span");
    prefixSpan.className = "option-prefix";
    prefixSpan.textContent = `[${prefixes[index]}]`;

    const labelSpan = document.createElement("span");
    labelSpan.textContent = optionText;

    btn.appendChild(prefixSpan);
    btn.appendChild(labelSpan);

    btn.addEventListener("click", () => handleAnswer(index));
    answersContainer.appendChild(btn);
  });

  const firstOption = answersContainer.querySelector("button");
  if (firstOption) {
    firstOption.focus();
  }
}

function handleAnswer(selectedIndex) {
  const current = QUESTIONS[currentQuestionIndex];
  if (selectedIndex === current.answer) {
    score += 1;
  }
  currentQuestionIndex += 1;
  updateHUD();
  renderQuestion();
}

function endQuiz(reason) {
  clearInterval(timerInterval);
  questionScreen.hidden = true;
  startScreen.hidden = true;
  resultScreen.hidden = false;

  resultReasonEl.textContent = reason;
  finalScoreEl.textContent = `${score} / ${QUESTIONS.length}`;
  restartBtn.focus();
}

// Event Listeners
startBtn.addEventListener("click", startQuiz);
restartBtn.addEventListener("click", startQuiz);
